#!/usr/bin/env node
// PreToolUse(Edit|Write): deny edits to generated, secret, or lockfile paths.
// Generated files are regenerated by a command; secrets are edited by the human.
import { relative } from 'node:path';

const raw = await readStdin();
let data;
try {
	data = JSON.parse(raw);
} catch {
	process.exit(0);
}

const file = data?.tool_input?.file_path;
if (!file) process.exit(0);
const rel = relative(process.cwd(), file).replaceAll('\\', '/');

const rules = [
	{
		test: (r) => /(^|\/)\.env(\..+)?$/.test(r) && !r.endsWith('.env.example'),
		reason: 'secrets file — the human edits this, not Claude (.env.example is fine)'
	},
	{
		test: (r) => /(^|\/)\.dev\.vars$/.test(r),
		reason: 'local runtime secrets — the human edits this (.dev.vars.example is fine)'
	},
	{
		test: (r) => /src\/lib\/paraglide\//.test(r),
		reason: 'generated Paraglide output — edit messages/{en,es}.json instead'
	},
	{
		test: (r) => r.endsWith('src/lib/server/db/auth.schema.ts'),
		reason: 'generated by Better Auth — run `pnpm auth:schema`'
	},
	{
		test: (r) => r.endsWith('worker-configuration.d.ts'),
		reason: 'generated by wrangler — run `pnpm gen`'
	},
	{
		test: (r) => /(^|\/)\.svelte-kit\//.test(r),
		reason: 'generated SvelteKit output'
	},
	{
		test: (r) => r.endsWith('pnpm-lock.yaml'),
		reason: 'lockfile — change dependencies via pnpm, not by hand'
	}
];

const hit = rules.find((rule) => rule.test(rel));
if (hit) {
	process.stdout.write(
		JSON.stringify({
			hookSpecificOutput: {
				hookEventName: 'PreToolUse',
				permissionDecision: 'deny',
				permissionDecisionReason: `Refusing to edit ${rel}: ${hit.reason}.`
			}
		})
	);
}
process.exit(0);

function readStdin() {
	return new Promise((resolve) => {
		let d = '';
		process.stdin.on('data', (c) => (d += c));
		process.stdin.on('end', () => resolve(d));
		process.stdin.on('error', () => resolve(d));
	});
}
